import sys
import os
from PIL import Image

def rebuild_image():
    # Read the 6-character hex strings generated by pixel_unpack.v
    filename = "rebuilt_pixels.txt"
    try:
        with open(filename, "r") as f:
            lines = [line.strip() for line in f.readlines() if line.strip()]
    except FileNotFoundError:
        print(f"Error: {filename} not found. Run the simulation first.")
        return

    # Create a fresh 1080p image canvas
    img = Image.new("RGB", (1920, 1080))
    pixels = img.load()

    idx = 0
    # Arrange the pixels in order, row by row, just like you specified
    for y in range(1080):
        for x in range(1920):
            if idx < len(lines):
                hex_val = lines[idx]
                if len(hex_val) == 6:
                    # Our Unpacker outputs {Blue, Green, Red}
                    b = int(hex_val[0:2], 16)
                    g = int(hex_val[2:4], 16)
                    r = int(hex_val[4:6], 16)
                    
                    # Decide the color and place it
                    pixels[x, y] = (r, g, b)
                idx += 1

    # Save the 1080p image
    img.save("rebuilt_pic.png")
    print(f"SUCCESS: Rebuilt {img.size[0]}x{img.size[1]} image saved to rebuilt_pic.png!")

if __name__ == "__main__":
    rebuild_image()
